package com.kisanprocure.service;
import com.kisanprocure.dto.booking.BookingDtos.*; import com.kisanprocure.dto.officer.OfficerDtos.*; import com.kisanprocure.entity.*; import com.kisanprocure.entity.enums.*; import com.kisanprocure.exception.ApiException; import com.kisanprocure.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class QueueService {
 private final BookingRepository bookings; private final QueueEntryRepository queue; private final CentreRepository centres;
 public QueueResponse bookingQueue(Long bookingId){QueueEntry q=queue.findByBookingId(bookingId).orElseThrow(()->new ApiException(404,"Queue entry not found")); List<QueueEntry> w=queue.findByCentreIdAndBookingSlotSlotDateAndStatusInOrderByQueuePosition(q.getCentre().getId(),q.getBooking().getSlot().getSlotDate(),List.of(QueueStatus.WAITING,QueueStatus.SERVING)); int ahead=(int)w.stream().filter(x->x.getQueuePosition()<q.getQueuePosition()).count(); Integer current=w.stream().filter(x->x.getStatus()==QueueStatus.SERVING).map(x->x.getBooking().getTokenNumber()).findFirst().orElse(null); return new QueueResponse(q.getBooking().getBookingId(),String.valueOf(q.getBooking().getTokenNumber()),q.getQueuePosition(),ahead,q.getEstimatedWait()==null?0:q.getEstimatedWait(),current==null?null:String.valueOf(current),q.getStatus().name()); }
 public CentreQueueResponse centreQueue(Long centreId, LocalDate date){Centre c=centres.findById(centreId).orElseThrow(()->new ApiException(404,"Centre not found")); List<QueueEntry> list=queue.findByCentreIdAndBookingSlotSlotDateAndStatusInOrderByQueuePosition(centreId,date,List.of(QueueStatus.WAITING,QueueStatus.SERVING)); int serving=(int)list.stream().filter(x->x.getStatus()==QueueStatus.SERVING).count(); int waiting=(int)list.stream().filter(x->x.getStatus()==QueueStatus.WAITING).count(); int estimate=list.stream().mapToInt(x->x.getEstimatedWait()==null?0:x.getEstimatedWait()).max().orElse(0); List<QueueItem> items=list.stream().map(x->new QueueItem(x.getQueuePosition(),x.getBooking().getTokenNumber(),x.getBooking().getBookingId(),x.getBooking().getExpectedQuantity(),x.getStatus().name(),x.getEstimatedWait())).toList(); return new CentreQueueResponse(centreId,c.getName(),new QueueListSummary(waiting,serving,0,estimate),items); }
 public QueueEntry next(Long centreId, LocalDate date){return queue.findTopByCentreIdAndBookingSlotSlotDateAndStatusOrderByQueuePositionAsc(centreId,date,QueueStatus.WAITING).orElseThrow(()->new ApiException(404,"No waiting farmer"));}
}
